import assert from "node:assert/strict";
import { pathToFileURL } from "node:url";

const { loadKeysFromJson } = await import(pathToFileURL(process.argv[2]));
for (const active_from of ["+010001-01-01T00:00:00.000Z", "-000001-01-01T00:00:00.000Z"]) {
  const key = { key_id: "test", alg: "Ed25519", public_key: Buffer.alloc(32).toString("base64url"),
    active_from, active_until: null };
  let result;
  try {
    const loaded = loadKeysFromJson({ workspace_id: "test", keys: [key] });
    result = { active_from, accepted: true, roundTrip: loaded[0].activeFrom.toISOString() };
  } catch (error) {
    result = { active_from, accepted: false, name: error.name };
  }
  console.log(JSON.stringify(result));
  assert.equal(result.accepted, false);
  assert.equal(result.name, "VerificationError");
}

programs.keyGuard:
import assert from "node:assert/strict";
import { pathToFileURL } from "node:url";

const { loadKeysFromJson } = await import(pathToFileURL(process.argv[2]));
let keyIdReads = 0;
const key = {
  get key_id() {
    keyIdReads += 1;
    if (keyIdReads > 1) throw new Error("post-guard key getter invoked");
    return "ephemeral-test-key";
  },
  alg: "Ed25519",
  public_key: Buffer.alloc(32).toString("base64url"),
  active_from: "2026-09-30T00:00:00.000Z",
  active_until: 15,
};
let result;
try {
  loadKeysFromJson({ workspace_id: "test", keys: [key] });
  result = { name: null, keyIdReads };
} catch (error) {
  result = { name: error.name, message: error.message, keyIdReads };
}
console.log(JSON.stringify(result));
assert.equal(result.name, "VerificationError");
assert.equal(keyIdReads, 1);

programs.keyIndex:
import assert from "node:assert/strict";
import { pathToFileURL } from "node:url";

const { loadKeysFromJson } = await import(pathToFileURL(process.argv[2]));
const id = process.argv[3];
const baseKey = {
  key_id: "test",
  alg: "Ed25519",
  public_key: Buffer.alloc(32).toString("base64url"),
  active_from: "2026-09-30T00:00:00.000Z",
  active_until: null,
};
const cases = {
  "2461": null,
  "2472": {},
  "2479": { ...baseKey, alg: "wrong" },
  "2494": { ...baseKey, active_until: 15 },
  "2512": { ...baseKey, public_key: Buffer.alloc(31).toString("base64url") },
  "2525": { ...baseKey, public_key_fingerprint: "wrong" },
};
let conversions = 0;
const index = { toString() { conversions += 1; throw new Error("caller index conversion"); } };
const keys = [];
keys.map = (callback) => [callback(cases[id], index, keys)];
let result;
try {
  loadKeysFromJson({ workspace_id: "test", keys });
  result = { name: null, conversions };
} catch (error) {
  result = { name: error.name, message: error.message, conversions };
}
console.log(JSON.stringify(result));
assert.equal(result.name, "Error");
assert.equal(conversions, 1);

