import assert from 'node:assert/strict'; import {randomBytes} from 'node:crypto'; import {pathToFileURL} from 'node:url';
const {matchesRef}=await import(pathToFileURL(process.argv[1]));
const key=new Proxy(new Uint8Array(randomBytes(32)),{get(target,name){if(name==='length')return 32;return Reflect.get(target,name,target)}});
const ref=process.argv[2]==='prefix'?'x'+'hmac-v1:'+'a'.repeat(64):'hmac-v1:'+'a'.repeat(64)+'x';
let observed;try{observed={returned:matchesRef(key,'record','value',ref),threw:false}}catch(error){observed={name:error.name,threw:true}}console.log(JSON.stringify(observed));assert.deepEqual(observed,{returned:false,threw:false});

